css:
/* 数据流（滚动型）：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景） */
:root{
  --ds-bg:#f6f8fb; --ds-fg:#1b2130; --ds-dim:#5f6a7d;
  --ds-accent:#0d9488; --ds-line:rgba(13,148,136,.24);
}
[data-reader-theme="night"]{
  --ds-bg:#05070b; --ds-fg:#dff6f2; --ds-dim:#7e8ba0;
  --ds-accent:#2dd4bf; --ds-line:rgba(45,212,191,.28);
}
html,body{margin:0;padding:0;height:100%;overflow:hidden;background:var(--ds-bg);color:var(--ds-fg);
  font-family:-apple-system,"Noto Sans CJK SC","Source Han Sans SC",sans-serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.8);}
body::before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.32;
  background:repeating-linear-gradient(90deg,transparent 0 26px,var(--ds-line) 26px 27px),
    repeating-linear-gradient(180deg,transparent 0 46px,rgba(127,127,127,.10) 46px 47px);
  -webkit-mask-image:linear-gradient(180deg,#000,transparent 60%);mask-image:linear-gradient(180deg,#000,transparent 60%);}
.ds-shell{position:relative;display:flex;flex-direction:column;height:100vh;}
.ds-head{flex:0 0 auto;display:flex;align-items:baseline;gap:.6em;padding:.7em 1.1em .5em;
  font-size:.76em;letter-spacing:.1em;color:var(--ds-dim);border-bottom:1px solid var(--ds-line);}
.ds-book{color:var(--ds-accent);}
.ds-chapter{flex:1 1 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.ds-pct{font-variant-numeric:tabular-nums;}
.ds-viewport{flex:1 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;position:relative;}
.ds-body{position:relative;padding:1em 1.2em 1.1em;}
.ds-body .reader-chapter-title{margin:0 0 .7em;font-size:1.32em;font-weight:650;}
.ds-body .reader-paragraph{margin:0 0 .92em;text-indent:2em;}
.ds-body p{margin:0 0 .92em;}
.ds-body a{color:var(--ds-accent);text-decoration:none;border-bottom:1px solid var(--ds-line);}
.ds-body blockquote{margin:0 0 1em;padding:.45em .9em;border-left:2px solid var(--ds-accent);color:var(--ds-dim);}
.ds-body code{background:rgba(127,127,127,.16);padding:.13em .34em;border-radius:3px;}
.ds-body pre{background:rgba(127,127,127,.12);padding:.8em;border-radius:4px;overflow-x:auto;}
.ds-body table{width:100%;border-collapse:collapse;}
.ds-body th,.ds-body td{border:1px solid var(--ds-line);padding:.34em .55em;}
.ds-foot{flex:0 0 auto;display:flex;justify-content:space-between;align-items:center;gap:.8em;
  padding:.5em 1.1em .7em;font-size:.72em;color:var(--ds-dim);font-variant-numeric:tabular-nums;
  border-top:1px solid var(--ds-line);}
.ds-foot-mark{opacity:.6;letter-spacing:.32em;}
.ds-body .reader-chapter-title{animation:ds-in .36s ease-out both;}
@keyframes ds-in{from{opacity:0;transform:translateY(4px);}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.ds-body .reader-chapter-title{animation:none;}}
